import React, { useState } from 'react';
import { RegexDefinition } from '../types';

const RegexUploader: React.FC<{ onRegexUpload: (regexList: RegexDefinition[]) => void }> = ({ onRegexUpload }) => {
    const [file, setFile] = useState<File | null>(null);
    const [error, setError] = useState<string | null>(null);

    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = event.target.files?.[0];
        if (selectedFile) {
            setFile(selectedFile);
            setError(null);
        }
    };

    const handleUpload = async () => {
        if (!file) {
            setError('Please select a file to upload.');
            return;
        }

        const reader = new FileReader();
        reader.onload = (e) => {
            const content = e.target?.result ? e.target.result.toString() : '';
            if (!content) return;
            try {
                const regexList = JSON.parse(content);
                onRegexUpload(regexList);
                setFile(null);
            } catch (err) {
                setError('Invalid file format. Please ensure it is a valid JSON file.');
            }
        };
        reader.readAsText(file);
    };

    return (
        <div>
            <input type="file" accept=".json" onChange={handleFileChange} />
            <button onClick={handleUpload}>Upload Regex</button>
            {error && <p style={{ color: 'red' }}>{error}</p>}
        </div>
    );
};

export default RegexUploader;
